INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, cr.id, 2, E'*a writing was recorded in their favour in heaven that they had executed righteousness... on the sinners* (Jubilees 30:23) — the day of 34:27 read as zeal-against-defilement; held in tension with the curse of Genesis 49:7, the sword not glorified.'
  FROM cross_reference_threads t
  JOIN _s301_ge34_lookup sv ON sv.edition_slug='canon' AND sv.book_slug='genesis' AND sv.chapter_number=34 AND sv.verse_number=27
  JOIN _s301_ge34_lookup tv ON tv.edition_slug='jubilees' AND tv.book_slug='jubilees' AND tv.chapter_number=30 AND tv.verse_number=23
  JOIN cross_references cr ON cr.source_verse_id=sv.verse_id AND cr.target_verse_id=tv.verse_id AND cr.source='manual'
 WHERE t.slug='genesis-34-levi-zealous-reckoned-for-righteousness'
ON CONFLICT (thread_id, cross_reference_id) DO NOTHING;
